GALLERY.forEach((g) => {
  const qi = scenes.findIndex((s) => s.u === g.u && s.type === "quiz");
  const dur = +(2.6 + g.items.length * 7 + 5).toFixed(1);   // 처음 훑기 2.6초 · 유물마다 7초 · 마지막 정리 5초 (hist-engine.js 의 TPL.gallery)
  scenes.splice(qi, 0, { u: g.u, type: "gallery", ch: "유물 따져 보기", title: g.title, head: g.head, sub: g.sub, fx: g.fx, pts: g.pts, dur, still: +(dur - 1.8).toFixed(1), items: g.items.map((img) => ({ img })) });
});

